    if(g.phase==="groups"&&!noPO)h+='<div class="row" style="margin-top:14px"><button class="p" id="fin"'+(allDone(g)?"":" disabled")+'>Avvia playoff con i primi '+Math.min(g.nq,g.players.length)+'</button></div>';
