    R.forEach(function(rd,r){
      h+='<div class="round"><h3>'+roundName(r,R.length)+'</h3>';
      rd.forEach(function(m,i){h+='<div class="match">'+slot(m,r,i,"a")+slot(m,r,i,"b")+'</div>'});
      h+='</div>';
    });
