  $("rchips").innerHTML=S.roster.length?S.roster.map(function(p,i){return'<span class="chip">'+esc(p)+'<button data-i="'+i+'" aria-label="Rimuovi '+esc(p)+'">×</button></span>'}).join(""):'<p class="empty">Nessun partecipante in lista.</p>';
