   +'<div class="row" style="margin-top:10px"><label class="row" style="gap:6px">Qualità <select id="s_q">'+s.qualities.map(function(q){return o(q,c.quality,q.replace("p"," p ").replace(/ p (\d+)/," p, $1 fps"))}).join("")+'</select></label>'
